  "words": [
    {
      "lesson": "w0-l1",
      "term": "Buddha",
      "say": "BOOD-dah",
      "old": "",
      "means": "'the one who woke up': a human teacher who saw clearly how hurt begins and how it ends. It is a title, not the name of a god."
    },
    {
      "lesson": "w0-l2",
      "term": "middle way",
      "say": "",
      "old": "",
      "means": "the balanced way: not too soft on yourself, not too hard"
    },
    {
      "lesson": "w0-l5",
      "term": "sutta",
      "say": "SOOT-tah",
      "old": "",
      "means": "one of the old talks, by the Buddha or his first students. Each lesson's story comes from one. Most of the 67 cards in this site's library are suttas."
    },
    {
      "lesson": "w1-l1",
      "term": "dukkha",
      "say": "DOOK-kah",
      "old": "",
      "means": "the 'not-quite-right' side of life, from big pain down to small restlessness. It does not mean 'life is misery'."
    },
    {
      "lesson": "w1-l3",
      "term": "impermanence",
      "say": "im-PUR-muh-nuns",
      "old": "",
      "means": "the library's word for 'everything changes'"
    },
    {
      "lesson": "w2-l1",
      "term": "craving",
      "say": "",
      "old": "",
      "means": "the 'gotta have it' or 'get it away from me' pull. The old word for it means 'thirst'. Wanting to learn or to be kind is not craving."
    },
    {
      "lesson": "w2-l3",
      "term": "feeling-tone",
      "say": "",
      "old": "",
      "means": "the instant 'nice', 'nasty' or 'neutral' tag on every experience. It is not an emotion like sad or angry, and it is not the same thing as dukkha."
    },
    {
      "lesson": "w2-l6",
      "term": "three fires",
      "say": "",
      "old": "",
      "means": "wanting, pushing away (from annoyance up to hate) and fog (not seeing clearly). The library calls them greed, hatred and delusion."
    },
    {
      "lesson": "w3-l2",
      "term": "not-self",
      "say": "",
      "old": "",
      "means": "'this is not me, not mine to command'. A way to hold things loosely. It does not mean 'you don't exist'."
    },
    {
      "lesson": "w3-l5",
      "term": "karma",
      "say": "KAR-mah",
      "old": "",
      "means": "something you do on purpose, and what grows from it. It is not fate."
    },
    {
      "lesson": "w3-l6",
      "term": "nirvana",
      "say": "nir-VAH-nah",
      "old": "",
      "means": "the cool peace when wanting, pushing away and fog stop burning. The old word means 'going out', like a flame."
    },
    {
      "lesson": "w4-l1",
      "term": "Eightfold Path",
      "say": "",
      "old": "",
      "means": "the library's name for this training plan. It counts the three jobs as eight steps. You do not need the eight yet."
    },
    {
      "lesson": "w5-l4",
      "term": "mindfulness",
      "say": "",
      "old": "",
      "means": "remembering to notice what is happening right now"
    },
    {
      "lesson": "w5-l5",
      "term": "meditation",
      "say": "",
      "old": "",
      "means": "exercise for your attention, done on purpose, a little at a time"
    },
    {
      "lesson": "w6-l2",
      "term": "goodwill",
      "say": "MET-tah",
      "old": "metta",
      "means": "wishing someone well, the way a friend would, with nothing wanted back"
    },
    {
      "lesson": "w6-l3",
      "term": "compassion",
      "say": "",
      "old": "",
      "means": "the wish to ease someone's pain, without drowning in it yourself"
    },
    {
      "lesson": "w6-l5",
      "term": "steady heart",
      "say": "",
      "old": "",
      "means": "a calm, balanced heart that still cares"
    },
    {
      "lesson": "w7-l1",
      "term": "Four Noble Truths",
      "say": "",
      "old": "",
      "means": "the Buddha's four answers: the hurt, its cause, its end, and the path of training"
    },
    {
      "lesson": "w7-l2",
      "term": "Sangha",
      "say": "SUNG-gah",
      "old": "",
      "means": "the Buddha's community: first the monks and nuns who train full time, and more loosely everyone who walks this path together"
    },
    {
      "lesson": "w7-l5",
      "term": "Dhamma",
      "say": "DUM-mah",
      "old": "",
      "means": "the Buddha's teaching; the way things really work"
    }
  ],
